ext('c12_pol_ch2',[
C("🇪🇺","यूरोपीय संघ की मुद्रा और संस्थाएँ",["साझी मुद्रा यूरो","संसद, आयोग, परिषद","सीमाओं की आवाजाही आसान","साझा बाज़ार"],"यूरोपीय संघ के कई देश साझी मुद्रा यूरो का उपयोग करते हैं। संघ की अपनी संसद, आयोग और परिषद जैसी संस्थाएँ हैं। इसके सदस्य देशों के बीच वस्तुओं, सेवाओं और लोगों की आवाजाही आसान है। एक साझा बाज़ार होने के कारण यह दुनिया का एक बहुत प्रभावशाली आर्थिक समूह बन गया है।"),
C("🌏","आसियान की विशेषताएँ",["सन उन्नीस सौ सरसठ में स्थापित","दक्षिण-पूर्व एशिया के देश","आसियान शैली: आपसी सहमति","आर्थिक सहयोग पर ज़ोर"],"आसियान की स्थापना सन उन्नीस सौ सरसठ में बैंकॉक घोषणा के साथ हुई थी। इसमें दक्षिण-पूर्व एशिया के देश शामिल हैं। इसका उद्देश्य आर्थिक विकास, सांस्कृतिक सहयोग और क्षेत्र में शांति बनाए रखना है। यह संगठन आपसी सहमति और बातचीत से निर्णय लेने पर ज़ोर देता है, जिसे आसियान शैली कहा जाता है।"),
C("🐉","चीन के आर्थिक सुधार",["सन उन्नीस सौ अठहत्तर","देंग शियाओपिंग","खुले द्वार की नीति","विशेष आर्थिक क्षेत्र"],"चीन ने सन उन्नीस सौ अठहत्तर में अपनी अर्थव्यवस्था में सुधार शुरू किए। देंग शियाओपिंग के नेतृत्व में खुले द्वार की नीति अपनाई गई और विशेष आर्थिक क्षेत्र बनाए गए। इन सुधारों से चीन में उद्योग और निर्यात तेज़ी से बढ़े। आज चीन दुनिया की बड़ी आर्थिक शक्तियों में गिना जाता है।"),
C("🤝","भारत और चीन के संबंध",["सन उन्नीस सौ बासठ का युद्ध","सीमा विवाद","आर्थिक व्यापार बढ़ा","सहयोग और प्रतिस्पर्धा"],"भारत और चीन के संबंधों में सन उन्नीस सौ बासठ का युद्ध एक बड़ा मोड़ था। दोनों के बीच सीमा विवाद अब भी बना हुआ है। फिर भी दोनों देशों के बीच व्यापार बहुत बढ़ा है। इसलिए संबंधों में सहयोग भी है और प्रतिस्पर्धा भी, और दोनों देश बातचीत से मुद्दे सुलझाने की कोशिश करते हैं।"),
],5)
ext('c12_pol_ch3',[
C("🕊️","भारत-पाकिस्तान संबंध",["विभाजन के बाद से तनाव","कश्मीर का मुद्दा","कई युद्ध","बातचीत और व्यापार के प्रयास"],"विभाजन के बाद भारत और पाकिस्तान के संबंध तनावपूर्ण रहे हैं। कश्मीर का मुद्दा सबसे बड़ा विवाद है। दोनों देशों के बीच कई युद्ध हुए हैं। बीच-बीच में बातचीत और व्यापार के प्रयास भी हुए हैं। दोनों के बीच शांति और विश्वास बहाली दक्षिण एशिया की स्थिरता के लिए ज़रूरी है।"),
C("🌾","नेपाल में लोकतंत्र की यात्रा",["राजतंत्र लंबे समय तक","जन आंदोलन","सन दो हज़ार आठ में गणराज्य","नया संविधान"],"नेपाल में लंबे समय तक राजतंत्र रहा। जनता के कई आंदोलनों के बाद सन दो हज़ार आठ में राजतंत्र समाप्त हुआ और नेपाल गणराज्य बना। इसके बाद नया संविधान बनाया गया। भारत और नेपाल के बीच खुली सीमा, व्यापार और सांस्कृतिक संबंध बहुत गहरे हैं।"),
C("🏝️","छोटे पड़ोसी देश",["भूटान: राजतंत्र से संवैधानिक राजतंत्र","मालदीव: द्वीपीय देश","श्रीलंका: सिंहली और तमिल मुद्दे","भारत के साथ संबंध"],"भूटान ने राजतंत्र से संवैधानिक राजतंत्र की ओर बदलाव किया है। मालदीव एक द्वीपीय देश है जिसकी अर्थव्यवस्था पर्यटन पर निर्भर है। श्रीलंका में लंबे समय तक सिंहली और तमिल समुदायों के बीच संघर्ष रहा। भारत इन सभी देशों के साथ शांति और सहयोग के संबंध बनाए रखना चाहता है।"),
C("🌉","क्षेत्रीय सहयोग के प्रयास",["सार्क की स्थापना","सन उन्नीस सौ पचासी","साफ्टा समझौता","आर्थिक सहयोग की संभावना"],"दक्षिण एशिया के देशों ने सहयोग बढ़ाने के लिए सन उन्नीस सौ पचासी में सार्क बनाया। इसका उद्देश्य आर्थिक और सामाजिक विकास में सहयोग है। साफ्टा नाम के समझौते से क्षेत्र में मुक्त व्यापार की कोशिश की गई। पर आपसी राजनीतिक तनावों के कारण सहयोग की पूरी संभावना अभी साकार नहीं हो पाई।"),
],5)
ext('c12_pol_ch4',[
C("🧾","संयुक्त राष्ट्र की स्थापना",["सन उन्नीस सौ पैंतालीस","द्वितीय विश्व युद्ध के बाद","मुख्यालय न्यूयॉर्क में","शांति और सुरक्षा बनाए रखना"],"संयुक्त राष्ट्र की स्थापना द्वितीय विश्व युद्ध के बाद सन उन्नीस सौ पैंतालीस में हुई। इसका मुख्य उद्देश्य अंतरराष्ट्रीय शांति और सुरक्षा बनाए रखना है। इसका मुख्यालय अमेरिका के न्यूयॉर्क शहर में है। आज दुनिया के लगभग सभी देश इसके सदस्य हैं।"),
C("🛡️","सुरक्षा परिषद के पाँच स्थायी सदस्य",["अमेरिका","रूस","चीन","ब्रिटेन और फ़्रांस"],"संयुक्त राष्ट्र की सुरक्षा परिषद में पाँच स्थायी सदस्य हैं। ये हैं, अमेरिका, रूस, चीन, ब्रिटेन और फ़्रांस। इन सभी के पास वीटो का अधिकार होता है। इनमें से कोई भी एक देश वीटो करे, तो कोई प्रस्ताव पारित नहीं हो सकता। इसी कारण सुधार की माँग लंबे समय से उठ रही है।"),
C("🏥","संयुक्त राष्ट्र की एजेंसियाँ",["विश्व स्वास्थ्य संगठन","यूनेस्को","यूनिसेफ","खाद्य और कृषि संगठन"],"संयुक्त राष्ट्र के अंतर्गत कई विशेष एजेंसियाँ काम करती हैं। विश्व स्वास्थ्य संगठन दुनिया भर में स्वास्थ्य सेवाओं पर काम करता है। यूनेस्को शिक्षा और संस्कृति के क्षेत्र में काम करता है। यूनिसेफ बच्चों की मदद करता है और खाद्य एवं कृषि संगठन भूख मिटाने की कोशिश करता है।"),
C("🇮🇳","सुरक्षा परिषद में भारत की दावेदारी",["सबसे बड़ा लोकतंत्र","दूसरी सबसे अधिक जनसंख्या","शांति सेना में बड़ा योगदान","स्थायी सीट की माँग"],"भारत सुरक्षा परिषद में स्थायी सदस्यता की माँग करता आया है। भारत दुनिया का सबसे बड़ा लोकतंत्र है और उसकी जनसंख्या बहुत ज़्यादा है। भारत संयुक्त राष्ट्र की शांति सेनाओं में भी बड़ा योगदान देता है। भारत का तर्क है कि आज की दुनिया को देखते हुए परिषद का विस्तार होना चाहिए।"),
],5)
ext('c12_pol_ch5',[
C("🚀","हथियार नियंत्रण संधियाँ",["परमाणु अप्रसार संधि","व्यापक परीक्षण प्रतिबंध संधि","भारत का रुख","संतुलित निरस्त्रीकरण की माँग"],"हथियारों को नियंत्रित करने के लिए कई संधियाँ बनी हैं। परमाणु अप्रसार संधि में पाँच देशों को ही परमाणु शक्ति माना गया। भारत ने इन संधियों को भेदभावपूर्ण मानते हुए उन पर हस्ताक्षर नहीं किए। भारत का कहना है कि निरस्त्रीकरण सभी देशों पर समान रूप से लागू होना चाहिए।"),
C("🔥","आतंकवाद की चुनौती",["निर्दोष लोगों पर हिंसा","सीमा पार से संगठित","अंतरराष्ट्रीय सहयोग ज़रूरी","विचारधारा और धन का स्रोत"],"आतंकवाद निर्दोष लोगों के विरुद्ध हिंसा का रास्ता है, जिसका उद्देश्य डर फैलाना और राजनीतिक दबाव बनाना होता है। यह अक्सर सीमा पार से संगठित होता है। इसे रोकने के लिए देशों के बीच खुफिया जानकारी की साझेदारी और कड़े कानूनों की ज़रूरत होती है। इसके धन के स्रोतों को रोकना भी बहुत ज़रूरी है।"),
C("🌡️","मानव सुरक्षा",["सिर्फ़ राज्य नहीं, व्यक्ति की सुरक्षा","भूख, बीमारी, गरीबी","मानवाधिकारों की रक्षा","नरसंहार और शरणार्थी संकट"],"मानव सुरक्षा का विचार है कि सुरक्षा केवल राज्य की नहीं, बल्कि हर व्यक्ति की होनी चाहिए। इसमें भूख, बीमारी, गरीबी और हिंसा से बचाव शामिल है। इसमें मानवाधिकारों की रक्षा भी आती है। नरसंहार और शरणार्थी संकट जैसी स्थितियाँ मानव सुरक्षा के लिए बड़ी चुनौती हैं।"),
C("🛡️","भारत की सुरक्षा रणनीति",["मज़बूत रक्षा तैयारी","आपसी सहयोग","संयुक्त राष्ट्र पर भरोसा","परमाणु हथियार पहले इस्तेमाल न करना"],"भारत की सुरक्षा रणनीति के कई पहलू हैं। इसमें अपनी सेना को मज़बूत रखना और पड़ोसियों से आपसी सहयोग बढ़ाना शामिल है। भारत संयुक्त राष्ट्र जैसी संस्थाओं पर भरोसा रखता है। परमाणु हथियारों के बारे में भारत की नीति है कि वह इनका पहले इस्तेमाल नहीं करेगा।"),
],5)
ext('c12_pol_ch6',[
C("🌍","रियो पृथ्वी सम्मेलन",["सन उन्नीस सौ बानवे","एजेंडा इक्कीस","जैव विविधता संधि","जलवायु परिवर्तन संधि"],"सन उन्नीस सौ बानवे में ब्राज़ील के रियो शहर में पृथ्वी सम्मेलन हुआ। इसमें पर्यावरण और विकास पर चर्चा हुई। यहाँ जलवायु परिवर्तन पर और जैव विविधता पर दो बड़ी संधियाँ की गईं। साथ ही सतत विकास के लिए एजेंडा इक्कीस नाम की कार्य योजना भी बनाई गई।"),
C("🧾","क्योटो प्रोटोकॉल",["ग्रीनहाउस गैसों में कमी","विकसित देशों पर बाध्यता","भारत और चीन पर बाध्यता नहीं","साझी लेकिन अलग-अलग ज़िम्मेदारी"],"क्योटो प्रोटोकॉल में विकसित देशों ने ग्रीनहाउस गैसों के उत्सर्जन में कटौती करने का लक्ष्य स्वीकार किया। भारत और चीन जैसे विकासशील देशों पर यह बाध्यता नहीं थी। इसके पीछे विचार यह था कि पर्यावरण की रक्षा की ज़िम्मेदारी सबकी है, पर उसकी मात्रा अलग-अलग है। इसे साझी लेकिन अलग-अलग ज़िम्मेदारी कहा गया।"),
C("🌊","साझी संपदा",["अंटार्कटिका","समुद्र","वायुमंडल","बाह्य अंतरिक्ष"],"कुछ क्षेत्र किसी एक देश के नहीं होते, उन्हें पूरी मानवता की साझी संपदा माना जाता है। अंटार्कटिका, समुद्र, वायुमंडल और बाह्य अंतरिक्ष इसके उदाहरण हैं। इन्हें बचाने के लिए सभी देशों को मिलकर काम करना होता है, और इस पर कई अंतरराष्ट्रीय समझौते भी हुए हैं।"),
C("🌱","स्थानीय समुदायों की भूमिका",["चिपको आंदोलन","नर्मदा बचाओ आंदोलन","परंपरागत ज्ञान","पर्यावरण रक्षा में सहभागिता"],"पर्यावरण की रक्षा में स्थानीय समुदायों की बड़ी भूमिका है। भारत में चिपको आंदोलन में लोगों ने पेड़ों से लिपटकर उन्हें कटने से बचाया। नर्मदा बचाओ आंदोलन में बाँधों के विस्थापितों ने आवाज़ उठाई। स्थानीय लोगों के पास पर्यावरण का परंपरागत ज्ञान भी होता है, जो संरक्षण में काम आता है।"),
],5)
ext('c12_pol_ch7',[
C("🌐","वैश्वीकरण के कारण",["संचार क्रांति","परिवहन में सुधार","अंतरराष्ट्रीय व्यापार समझौते","इंटरनेट का प्रसार"],"वैश्वीकरण के पीछे कई कारण हैं। टेलीफ़ोन और इंटरनेट से संचार आसान हो गया है। हवाई और समुद्री परिवहन के सुधार से वस्तुओं की आवाजाही तेज़ हुई। अंतरराष्ट्रीय व्यापार समझौतों से सीमाओं की बाधाएँ घटीं। इन सबने दुनिया को एक-दूसरे के बहुत करीब ला दिया।"),
C("💱","आर्थिक वैश्वीकरण के पहलू",["पूँजी का प्रवाह","बहुराष्ट्रीय कंपनियाँ","व्यापार का विस्तार","रोज़गार के नए अवसर"],"आर्थिक वैश्वीकरण में पूँजी, वस्तुएँ और सेवाएँ देशों के बीच आसानी से आती-जाती हैं। बहुराष्ट्रीय कंपनियाँ कई देशों में काम करती हैं। इससे व्यापार का विस्तार होता है और कई जगह रोज़गार के नए अवसर बनते हैं। पर इसका लाभ सभी तक समान रूप से नहीं पहुँचता।"),
C("👗","सांस्कृतिक एकरूपता का डर",["पश्चिमी संस्कृति का असर","भाषाओं और परंपराओं पर दबाव","संस्कृति का मिश्रण भी","संस्कृतियों का आदान-प्रदान"],"वैश्वीकरण के कारण यह चिंता जताई जाती है कि दुनिया भर में पश्चिमी संस्कृति का प्रभाव बढ़ रहा है और स्थानीय भाषाओं और परंपराओं पर दबाव आ रहा है। दूसरी ओर, इससे संस्कृतियों का मेल और आदान-प्रदान भी होता है। इसलिए स्थानीय पहचान को बचाते हुए बदलाव को अपनाना चाहिए।"),
C("🏭","वैश्वीकरण के विरोध के कारण",["छोटे उद्योगों पर संकट","किसानों की चिंता","असमानता का बढ़ना","पर्यावरण पर असर"],"वैश्वीकरण का कई लोग विरोध भी करते हैं। उनका कहना है कि बड़ी कंपनियाँ छोटे उद्योगों और किसानों को नुकसान पहुँचाती हैं। उनके अनुसार इससे अमीर और गरीब के बीच अंतर बढ़ता है और पर्यावरण पर भी बुरा असर पड़ता है। इसलिए कई लोग नियमों के साथ संतुलित वैश्वीकरण की माँग करते हैं।"),
],5)
ext('c12_pol_ch8',[
C("🗺️","रियासतों का एकीकरण",["सरदार पटेल की भूमिका","पाँच सौ से ज़्यादा रियासतें","विलय पत्र पर हस्ताक्षर","हैदराबाद और जूनागढ़"],"आज़ादी के समय भारत में पाँच सौ से ज़्यादा रियासतें थीं। सरदार वल्लभभाई पटेल ने अपनी कुशलता से इन्हें भारत में मिलाया। ज़्यादातर राजाओं ने विलय पत्र पर हस्ताक्षर कर दिए। जूनागढ़ और हैदराबाद जैसी कुछ रियासतों के विलय में कठिनाई आई, जिन्हें बाद में हल किया गया।"),
C("🧭","राज्यों का पुनर्गठन",["भाषाई राज्यों की माँग","पोट्टी श्रीरामुलु का बलिदान","राज्य पुनर्गठन आयोग","सन उन्नीस सौ छप्पन का अधिनियम"],"आज़ादी के बाद लोग भाषा के आधार पर राज्य बनाने की माँग करने लगे। आंध्र प्रदेश के लिए पोट्टी श्रीरामुलु के अनशन और बलिदान के बाद सरकार को झुकना पड़ा। राज्य पुनर्गठन आयोग बनाया गया, जिसकी सिफ़ारिशों पर सन उन्नीस सौ छप्पन में राज्य पुनर्गठन अधिनियम पास हुआ।"),
C("📢","भाषा का विवाद",["हिंदी और अंग्रेज़ी","दक्षिण में हिंदी का विरोध","तीन भाषा सूत्र","बहुभाषी राष्ट्र"],"आज़ादी के बाद राजभाषा के रूप में हिंदी को बढ़ावा देने पर कई गैर-हिंदी भाषी राज्यों में विरोध हुआ। इसके बाद तीन भाषा सूत्र अपनाया गया। भारत की भाषाई विविधता ही उसकी ताक़त है, इसलिए यहाँ किसी एक भाषा को थोपने के बजाय सभी भाषाओं के सम्मान पर ज़ोर दिया गया।"),
C("🏞️","पूर्वोत्तर और कश्मीर की चुनौतियाँ",["पूर्वोत्तर में अलगाव की माँगें","कश्मीर पर विवाद","बातचीत और समझौते","राष्ट्र निर्माण की निरंतर प्रक्रिया"],"पूर्वोत्तर के कुछ क्षेत्रों में अलगाव की माँगें उठीं और कश्मीर पर पाकिस्तान के साथ विवाद भी चलता रहा। सरकार ने कई जगह बातचीत और समझौतों से रास्ता निकाला। राष्ट्र निर्माण एक बार में पूरा होने वाला काम नहीं है, यह लगातार चलने वाली प्रक्रिया है।"),
],5)
